def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def fail(message: str) -> None:
    print("\n" + "=" * 92)
    print("DỪNG AN TOÀN")
    print(message)
    print("Bộ cài V4 không thực hiện sáp nhập và không chủ động ghi phocap.db.")
    print("=" * 92)
    raise SystemExit(1)


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + ".v4_tmp")
    temp.write_bytes(data)
    os.replace(temp, path)


def main() -> None:
    root = Path(__file__).resolve().parent
    db = root / "data" / "phocap.db"
    print("=" * 92)
    print("BÀI SÁP NHẬP V4 - THỰC HIỆN SÁP NHẬP AN TOÀN")
    print(f"Dự án: {root}")
    print("Bộ cài chỉ mở cơ chế V4; KHÔNG chạy bất kỳ phương án sáp nhập nào.")
    print("=" * 92)

    if not (root / "app").is_dir() or not db.exists():
        fail(r"Hãy chép bộ cài vào đúng thư mục gốc C:\PhoCap rồi chạy lại.")

    # Khóa các thành phần nền mà V4 dựa vào. Không tự ghi đè nếu khác bản đã kiểm thử.
    for rel, expected in DEPENDENCY_HASHES.items():
        path = root / rel
        if not path.exists():
            fail(f"Thiếu tệp nền bắt buộc: {rel}")
        got = sha256_file(path)
        if got != expected:
            fail(
                f"Tệp nền {rel} khác phiên bản V3 đã kiểm thử.\n"
                f"SHA hiện tại: {got}\nSHA cần có: {expected}"
            )

    # Tệp V3 được phép ở đúng V3 hoặc đã là V4 khi chạy lại installer.
    for rel, expected_v4 in EXPECTED_V4.items():
        path = root / rel
        if path.exists():
            got = sha256_file(path)
            allowed = {expected_v4}
            if rel in EXPECTED_V3:
                allowed.add(EXPECTED_V3[rel])
            if got not in allowed:
                fail(
                    f"Tệp {rel} đã bị thay đổi ngoài Bài V3/V4 nên bộ cài không tự ghi đè.\n"
                    f"SHA hiện tại: {got}"
                )
        elif rel in EXPECTED_V3:
            fail(f"Thiếu tệp V3 bắt buộc: {rel}")

    db_before = sha256_file(db)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_bai_sap_nhap_v4_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    for rel in EXPECTED_V4:
        src = root / rel
        if src.exists():
            dst = backup_dir / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    try:
        for rel, encoded in EMBEDDED_FILES.items():
            atomic_write(root / rel, base64.b64decode(encoded))

        for rel, expected in EXPECTED_V4.items():
            got = sha256_file(root / rel)
            if got != expected:
                raise RuntimeError(f"SHA sau cài không đúng ở {rel}: {got}")

        py_compile.compile(str(root / "app" / "routers" / "school_merger.py"), doraise=True)
        py_compile.compile(str(root / "app" / "services" / "school_merger_preview_service.py"), doraise=True)
        py_compile.compile(str(root / "app" / "services" / "school_merger_execution_service.py"), doraise=True)

        sys.path.insert(0, str(root))
        importlib.invalidate_caches()
        from app.services.school_merger_official_registry import list_official_registry_plans
        from app.services.school_merger_preview_service import build_official_plan_impact_preview
        from app.services.school_merger_execution_service import (
            OFFICIAL_CONFIRM_PHRASE,
            annotate_official_plan_execution_status,
        )

        if OFFICIAL_CONFIRM_PHRASE != "SAP NHAP":
            raise RuntimeError("Câu xác nhận V4 không đúng thiết kế: SAP NHAP")

        cua_lo = [
            p for p in list_official_registry_plans(level_code="TH")
            if p.get("commune_excel") == "Cửa Lò"
        ]
        if len(cua_lo) != 4:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 4 nhóm, hiện có {len(cua_lo)}.")

        annotated = annotate_official_plan_execution_status(cua_lo)
        mapped = [p for p in annotated if str(p.get("action_type") or "").upper() == "MAPPED"]
        if len(mapped) != 3:
            raise RuntimeError(f"Cửa Lò - Tiểu học phải có 3 nhóm nguồn→đích, hiện có {len(mapped)}.")

        preview_lines = []
        for plan in mapped:
            preview = build_official_plan_impact_preview(str(plan["id"]))
            if preview.get("blockers"):
                raise RuntimeError(
                    f"Phương án {plan['id']} bị chặn trước khi mở V4: "
                    + " | ".join(preview.get("blockers") or [])
                )
            if not preview.get("simulation_ok") or not preview.get("safe_for_future_execution"):
                raise RuntimeError(f"Phương án {plan['id']} chưa vượt qua mô phỏng V4.")
            if not preview.get("database_fingerprint") or not preview.get("fingerprint"):
                raise RuntimeError(f"Phương án {plan['id']} thiếu fingerprint V4.")
            src_names = ", ".join(
                str(x.get("name") or x.get("excel_name") or "")
                for x in preview.get("source_schools") or []
            )
            dst_name = str((preview.get("target_school") or {}).get("name") or "")
            summary = preview.get("summary") or {}
            preview_lines.append(
                f" - {src_names} -> {dst_name}: MÔ PHỎNG ĐẠT; "
                f"CURRENT/FUTURE={summary.get('direct_move_rows', 0)}; "
                f"PAST giữ={summary.get('historical_preserve_rows', 0)}; "
                f"rollover đội ngũ={summary.get('staff_rollover_candidates', 0)}"
            )

        # Kiểm tra route V4 đã mở nhưng route thực hiện cũ vẫn khóa.
        router_text = (root / "app" / "routers" / "school_merger.py").read_text(encoding="utf-8")
        if '@router.post("/phuong-an/thuc-hien/{plan_id}"' not in router_text:
            raise RuntimeError("Chưa cài endpoint thực hiện phương án chính thức V4.")
        if '@router.get("/phuong-an/ket-qua/{plan_id}"' not in router_text:
            raise RuntimeError("Chưa cài endpoint kết quả V4.")
        legacy_pos = router_text.find('@router.post("/thuc-hien"')
        legacy_lock = router_text.find("chặn tuyệt đối endpoint thực hiện ở backend", legacy_pos)
        if legacy_pos < 0 or legacy_lock < 0:
            raise RuntimeError("Không còn nhận diện được khóa endpoint thực hiện cũ.")

        # Jinja syntax.
        from jinja2 import Environment, FileSystemLoader
        env = Environment(loader=FileSystemLoader(str(root / "app" / "templates")))
        for name in (
            "data_tools/school_merger_plans.html",
            "data_tools/school_merger_preview.html",
            "data_tools/school_merger_result.html",
        ):
            env.get_template(name)

        db_after = sha256_file(db)
        if db_before != db_after:
            raise RuntimeError("SHA256 phocap.db đã thay đổi trong quá trình cài/kiểm thử V4.")

    except Exception as exc:
        # Hoàn tác mã nguồn về đúng trạng thái trước installer.
        for rel in EXPECTED_V4:
            backup = backup_dir / rel
            dest = root / rel
            if backup.exists():
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, dest)
            elif rel not in EXPECTED_V3 and dest.exists():
                try:
                    dest.unlink()
                except Exception:
                    pass
        fail("Cài đặt/kiểm thử V4 thất bại và mã nguồn đã được hoàn tác: " + str(exc))

    report = [
        "BÀI SÁP NHẬP V4 - CÀI ĐẶT THÀNH CÔNG",
        f"Thời gian: {datetime.now().isoformat(timespec='seconds')}",
        f"Dự án: {root}",
        f"Backup mã nguồn trước V4: {backup_dir}",
        "",
        "TỆP ĐÃ CÀI:",
        *[f" - {rel}" for rel in EXPECTED_V4],
        "",
        "KIỂM TRA AN TOÀN CỦA BỘ CÀI:",
        " - phocap.db SHA256 trước/sau cài: KHÔNG THAY ĐỔI.",
        " - Bộ cài KHÔNG thực hiện bất kỳ phương án sáp nhập nào.",
        " - Endpoint thực hiện cũ /thuc-hien: VẪN KHÓA.",
        " - Chỉ endpoint /phuong-an/thuc-hien/{plan_id} được mở cho phương án chính thức.",
        " - Câu xác nhận bắt buộc: SAP NHAP.",
        " - V4 có backup tự động + BEGIN IMMEDIATE + 1 transaction + hậu kiểm trước COMMIT.",
        " - Có nhật ký chống thực hiện cùng phương án lần hai.",
        "",
        "KIỂM TRA CỬA LÒ - TIỂU HỌC TRƯỚC KHI MỞ V4:",
        *preview_lines,
        "",
        "BƯỚC KIỂM TRA GIAO DIỆN SAU CÀI:",
        " 1) Khởi động lại Uvicorn.",
        " 2) Vào Sáp nhập trường -> Danh sách phương án chính thức.",
        " 3) Chọn 2026-2027 -> Cửa Lò -> Tiểu học.",
        " 4) Dòng Nghi Hoà -> Nghi Hải: bấm XEM TRƯỚC TÁC ĐỘNG.",
        " 5) Phải thấy mục 7 - Xác nhận thực hiện thật V4.",
        " 6) Chưa bấm THỰC HIỆN cho tới khi đã chụp màn hình V4 và đối chiếu lần cuối.",
    ]
    report_path = root / f"bao_cao_cai_bai_sap_nhap_v4_{stamp}.txt"
    report_path.write_text("\n".join(report) + "\n", encoding="utf-8")

    print("\n" + "\n".join(report))


if __name__ == "__main__":
    main()
